   190	      }
   191	    }
   192	    return bag.pop();
   193	  }
   194	
   195	  function cleanQueue(queue) {
   196	    if (!Array.isArray(queue)) return [];
   197	    return queue
   198	      .map(function (p) { return String(p).toUpperCase(); })
   199	      .filter(function (p) { return TYPES.indexOf(p) !== -1; });
   200	  }
   201	
   202	  // Keep at least one upcoming piece so the preview has something to show.
   203	  function fillUpcoming() {
   204	    while (upcoming.length < 1) upcoming.push(randomPiece());
