   206	
   207	  function pieceCells(p, rot, row, col) {
   208	    return ROTATIONS[p.type][rot].map(function (o) { return [row + o[0], col + o[1]]; });
   209	  }
   210	
   211	  function fits(p, rot, row, col) {
   212	    var cells = pieceCells(p, rot, row, col);
   213	    for (var i = 0; i < cells.length; i++) {
   214	      var r = cells[i][0], c = cells[i][1];
   215	      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
   216	      if (board[r][c]) return false;
   217	    }
   218	    return true;
   219	  }
   220	
   221	  function spawn() {
   222	    fillUpcoming();
   223	    var type = upcoming.shift();
   224	    fillUpcoming();
   225	    var p = { type: type, rot: 0, row: SPAWN[type][0], col: SPAWN[type][1], lockTicks: 0, lockResets: 0 };
   226	    if (!fits(p, p.rot, p.row, p.col)) {
   227	      current = null;
   228	      status = "over";
   229	      stopTimer();
   230	      return;
   231	    }
   232	    current = p;
   233	  }
   234	
   235	  function tryMove(dr, dc) {
   236	    if (!current) return false;
   237	    if (!fits(current, current.rot, current.row + dr, current.col + dc)) return false;
   238	    current.row += dr;
   239	    current.col += dc;
   240	    if (dr > 0) current.lockTicks = 0;
   241	    return true;
   242	  }
   243	
   244	  function isResting() {
   245	    return !fits(current, current.rot, current.row + 1, current.col);
   246	  }
   247	
   248	  // Sideways move. If the piece was resting, this restarts its lock delay (capped per piece).
   249	  function tryShift(dc) {
   250	    if (!current) return false;
   251	    var resting = isResting();
   252	    if (!tryMove(0, dc)) return false;
   253	    if (resting && current.lockResets < MAX_LOCK_RESETS) {
   254	      current.lockResets++;
   255	      current.lockTicks = 0;
   256	    }
   257	    return true;
   258	  }
   259	
   260	  // Clockwise rotation. If the rotated shape does not fit in place, try sideways shifts only
   261	  // (a vertical kick would let a resting piece climb and stay in the air). If nothing fits,
   262	  // the piece is left untouched.
   263	  function tryRotateCW() {
