   270	        current.rot = rot;
   271	        current.col = col;
   272	        return true;
   273	      }
   274	    }
   275	    return false;
   276	  }
   277	
   278	  function clearLines() {
   279	    var kept = board.filter(function (row) {
   280	      return row.some(function (cell) { return !cell; });
   281	    });
   282	    var cleared = ROWS - kept.length;
   283	    if (cleared === 0) return;
   284	    while (kept.length < ROWS) {
