   304	    clearLines();
   305	    spawn();
   306	  }
   307	
   308	  // One gravity step. The real timer and __tetris.tick both run this.
   309	  function gravityStep() {
   310	    if (status !== "running" || !current) return;
   311	    if (tryMove(1, 0)) return;
   312	    current.lockTicks++;
   313	    if (current.lockTicks >= LOCK_DELAY) lockPiece();
   314	  }
   315	
   316	  function performAction(action) {
   317	    if (status !== "running" || !current) return;
   318	    switch (action) {
   319	      case "left": tryShift(-1); break;
   320	      case "right": tryShift(1); break;
   321	      case "softDrop":
