   327	        break;
   328	      case "rotateCW":
   329	      case "rotate": tryRotateCW(); break;
   330	    }
   331	  }
   332	
   333	  // ---- Timer ----
   334	  function gravityInterval() {
   335	    return Math.max(100, 1000 - (level - 1) * 90);
   336	  }
   337	
   338	  function startTimer() {
   339	    stopTimer();
