   341	      gravityStep();
   342	      render();
   343	    }, gravityInterval());
   344	  }
   345	
   346	  function stopTimer() {
   347	    if (timer !== null) {
   348	      clearInterval(timer);
   349	      timer = null;
   350	    }
   351	  }
   352	
   353	  function newGame(queue) {
   354	    board = emptyBoard();
   355	    bag = [];
   356	    upcoming = cleanQueue(queue);
   357	    score = 0;
   358	    level = 1;
   359	    lines = 0;
   360	    status = "running";
   361	    current = null;
