   366	  // ---- Rendering (synchronous) ----
   367	  var boardEl = document.getElementById("board");
   368	  var overlayEl = document.getElementById("overlay");
   369	  var scoreEl = document.getElementById("score");
   370	  var levelEl = document.getElementById("level");
   371	  var linesEl = document.getElementById("lines");
   372	  var previewEl = document.getElementById("preview");
   373	  var cellEls = [];
   374	  var previewEls = [];
   375	
   376	  (function buildDom() {
   377	    for (var r = 0; r < ROWS; r++) {
   378	      cellEls.push([]);
   379	      for (var c = 0; c < COLS; c++) {
   380	        var el = document.createElement("div");
   381	        el.className = "cell";
   382	        el.setAttribute("data-testid", "cell");
   383	        el.setAttribute("data-row", String(r));
   384	        el.setAttribute("data-col", String(c));
